use xiom.io;

use xiom.string;
fn main() {
  let adjective: Str = "awesome";
  let noun: Str = "coder";
  let space: Str = " ";
  let phrase: Str = string.str_concat(adjective, string.str_concat(space, noun));
  io.println(phrase);
}
